 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    def repeated_separator_lines(horizontal):
        length = h if horizontal else w
        cross = w if horizontal else h
        found = []
        for i in range(length):
            vals = [grid[i][j] for j in range(cross)] if horizontal else [grid[j][i] for j in range(cross)]
            if len(set(vals)) == 1:
                found.append((i, vals[0]))
        # Use the color of full-width/full-height lines that occur repeatedly;
        # these lines delimit identical-sized tiles.
        by_color = {}
        for i, color in found:
            by_color.setdefault(color, []).append(i)
        options = []
        for color, positions in by_color.items():
            if len(positions) < 1:
                continue
            bounds = [-1] + positions + [length]
            gaps = [bounds[k + 1] - bounds[k] - 1 for k in range(len(bounds) - 1)]
            if gaps and len(set(gaps)) == 1 and gaps[0] > 0:
                options.append((len(positions), gaps[0], color, positions))
        if not options:
            return None
        _, size, color, positions = max(options)
        return size, color, positions

    # Detect a set of evenly spaced divider lines in either direction.
    horizontal = repeated_separator_lines(True)
    vertical = repeated_separator_lines(False)
    if horizontal is None and vertical is None:
        return [row[:] for row in grid]

    # Prefer the orientation with the more complete, clearly repeated tiling.
    use_horizontal = horizontal is not None and (vertical is None or horizontal[0] >= vertical[0])
    info = horizontal if use_horizontal else vertical
    size, separator_color, positions = info
    length = h if use_horizontal else w
    starts = []
    p = 0
    separator_set = set(positions)
    while p < length:
        if p in separator_set:
            p += 1
        else:
            starts.append(p)
            p += size
    # Collect non-background pixels in each corresponding location. The
    # separator color is excluded; remaining most-common color is background.
    cells = []
    if use_horizontal:
        for a in starts:
            for r in range(a, a + size):
                cells.extend(grid[r])
    else:
        for a in starts:
            for r in range(h):
                cells.extend(grid[r][a:a + size])
    counts = {}
    for value in cells:
        if value != separator_color:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get) if counts else separator_color

    if use_horizontal:
        motif = [[background] * w for _ in range(size)]
        for a in starts:
            for dr in range(size):
                for c in range(w):
                    value = grid[a + dr][c]
                    if value != background and value != separator_color:
                        motif[dr][c] = value
        out = [row[:] for row in grid]
        for a in starts:
            for dr in range(size):
                out[a + dr] = motif[dr][:]
        return out
    else:
        motif = [[background] * size for _ in range(h)]
        for a in starts:
            for r in range(h):
                for dc in range(size):
                    value = grid[r][a + dc]
                    if value != background and value != separator_color:
                        motif[r][dc] = value
        out = [row[:] for row in grid]
        for a in starts:
            for r in range(h):
                out[r][a:a + size] = motif[r][:]
        return out
